export const LANGS: { code: Lang; name: string }[] = [
  { code: 'fr', name: 'Français' }, { code: 'en', name: 'English' }, { code: 'pt', name: 'Português' },
  { code: 'ee', name: 'Éwé' }, { code: 'gej', name: 'Mina' },
];
/** Une langue n'apparaît dans le sélecteur que si au moins 90 % des textes sont traduits. */
export function availableLangs() {
  const total = Object.keys(T.fr).length;
  return LANGS.filter((l) => l.code === 'fr' || l.code === 'en'
    || Object.keys(T[l.code]).filter((k) => T[l.code][k]).length / total >= 0.9);
}

interface Value { lang: Lang; setLang: (l: Lang) => void; t: (k: string) => string; f: (n: number) => string }
const Ctx = createContext<Value | null>(null);

export function I18n({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>('fr');
  useEffect(() => {
    const saved = localStorage.getItem('lang');
    if (availableLangs().some((l) => l.code === saved)) setLangState(saved as Lang);
  }, []);
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  const setLang = (l: Lang) => { setLangState(l); localStorage.setItem('lang', l); };
  const t = (k: string) => T[lang][k] || EXTRA_TEXT[lang]?.[k] || T.fr[k] || EXTRA_TEXT.fr?.[k] || k;
  const f = (n: number) => Number(n).toLocaleString(lang === 'en' ? 'en-US' : lang === 'pt' ? 'pt-PT' : 'fr-FR') + ' F';
  return <Ctx.Provider value={{ lang, setLang, t, f }}>{children}</Ctx.Provider>;
}

export function useI18n(): Value {
  const v = useContext(Ctx);
  if (!v) throw new Error('useI18n must be used inside <I18n>');
  return v;
}
